CREATE TABLE `academy_payout_accounts` (`academy_id` text PRIMARY KEY NOT NULL,`stripe_account_id` text NOT NULL,`dashboard_type` text DEFAULT 'express' NOT NULL,`onboarding_status` text DEFAULT 'pending' NOT NULL,`transfers_status` text DEFAULT 'inactive' NOT NULL,`payouts_status` text DEFAULT 'inactive' NOT NULL,`good_standing` integer DEFAULT true NOT NULL,`details_submitted` integer DEFAULT false NOT NULL,`created_by` text NOT NULL,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE UNIQUE INDEX `academy_payout_stripe_account_unique` ON `academy_payout_accounts` (`stripe_account_id`);
CREATE TABLE `revenue_receipts` (`id` text PRIMARY KEY NOT NULL,`provider_charge_id` text NOT NULL,`provider_balance_transaction_id` text,`currency` text DEFAULT 'usd' NOT NULL,`gross_cents` integer NOT NULL,`tax_cents` integer DEFAULT 0 NOT NULL,`processing_fee_cents` integer DEFAULT 0 NOT NULL,`refund_cents` integer DEFAULT 0 NOT NULL,`dispute_cents` integer DEFAULT 0 NOT NULL,`net_cents` integer NOT NULL,`status` text DEFAULT 'reconciling' NOT NULL,`period_key` text NOT NULL,`cohort_id` text,`occurred_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE UNIQUE INDEX `revenue_receipt_charge_unique` ON `revenue_receipts` (`provider_charge_id`);
CREATE INDEX `revenue_receipt_period_idx` ON `revenue_receipts` (`period_key`,`status`);
CREATE TABLE `revenue_pool_cohorts` (`id` text PRIMARY KEY NOT NULL,`period_key` text NOT NULL,`currency` text DEFAULT 'usd' NOT NULL,`net_revenue_cents` integer NOT NULL,`operations_cents` integer NOT NULL,`founder_cents` integer NOT NULL,`academy_pool_cents` integer NOT NULL,`eligible_academy_count` integer NOT NULL,`remainder_cents` integer DEFAULT 0 NOT NULL,`reserve_days` integer DEFAULT 60 NOT NULL,`available_at` integer NOT NULL,`status` text DEFAULT 'reserved' NOT NULL,`closed_by` text NOT NULL,`closed_at` integer NOT NULL,`released_at` integer);
CREATE UNIQUE INDEX `revenue_pool_period_currency_unique` ON `revenue_pool_cohorts` (`period_key`,`currency`);
CREATE TABLE `academy_pool_allocations` (`id` text PRIMARY KEY NOT NULL,`cohort_id` text NOT NULL,`academy_id` text NOT NULL,`stripe_account_id` text NOT NULL,`amount_cents` integer NOT NULL,`currency` text DEFAULT 'usd' NOT NULL,`status` text DEFAULT 'reserved' NOT NULL,`provider_transfer_id` text,`attempts` integer DEFAULT 0 NOT NULL,`failure_code` text,`paid_at` integer,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE UNIQUE INDEX `academy_pool_cohort_academy_unique` ON `academy_pool_allocations` (`cohort_id`,`academy_id`);
CREATE INDEX `academy_pool_release_idx` ON `academy_pool_allocations` (`status`,`cohort_id`);
CREATE TABLE `founder_distributions` (`id` text PRIMARY KEY NOT NULL,`cohort_id` text NOT NULL,`amount_cents` integer NOT NULL,`currency` text DEFAULT 'usd' NOT NULL,`status` text DEFAULT 'payable' NOT NULL,`authorized_by` text,`paid_at` integer,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE UNIQUE INDEX `founder_distribution_cohort_unique` ON `founder_distributions` (`cohort_id`);
